exercises.solution:
package main

import "fmt"

type Counter struct {
    Value int
}

func (c Counter) Increment() Counter {
    return Counter{Value: c.Value + 1}
}

func main() {
    c := Counter{Value: 5}
    fmt.Println(c.Increment())
}

