}

exercises.solution:
package main

import "fmt"

type Builder struct {
    result string
}

func (b Builder) Add(s string) Builder {
    b.result += s
    return b
}

func (b Builder) Build() string {
    return b.result
}

func main() {
    b := Builder{}
    result := b.Add("Hello").Add("World").Build()
    fmt.Println(result)
}

