}

exercises.solution:
package main

import "fmt"
import "math"

type Circle struct {
    Radius float64
}

func (c Circle) Area() float64 {
    return math.Pi * c.Radius * c.Radius
}

func (c Circle) Perimeter() float64 {
    return 2 * math.Pi * c.Radius
}

func main() {
    c := Circle{Radius: 5.0}
    fmt.Println(c.Area())
    fmt.Println(c.Perimeter())
}

